1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.server.http.HttpHeader;
5	import net.officefloor.server.http.ServerHttpConnection;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.dao.DataAccessException;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	
13	/**
14	 * First step of {@code POST /api/owners}: honours an optional {@code Idempotency-Key} header. When
15	 * the key has already been recorded for a completed create, this responds 200 with the originally
16	 * created owner and does NOT trigger the {@code proceed} branch, so the create pipeline is skipped
17	 * and no duplicate is made (nor any later duplicate/quota rule applied). Otherwise it triggers
18	 * {@code proceed} to run the normal create pipeline, after which {@link RegisterIdempotency} records
19	 * the key against the newly saved owner.
20	 */
21	public class CheckIdempotencyKey {
22	
23	    /** Client-supplied header naming the idempotency key. */
24	    public static final String HEADER = "Idempotency-Key";
25	
26	    /** The {@code proceed} branch: run the normal create pipeline (wired to {@code validate}). */
27	    @FunctionalInterface
28	    public interface ProceedFlow {
29	        void proceed();
30	    }
31	
32	    public void service(ServerHttpConnection connection, IdempotencyStore store,
33	            OwnerRepository ownerRepository, OwnerMapper ownerMapper,
34	            @Flow("proceed") ProceedFlow proceed, ObjectResponse<OwnerDto> response) {
35	        String key = header(connection);
36	        if (key != null) {
37	            Integer ownerId = store.find(key);
38	            if (ownerId != null) {
39	                Owner existing = findQuietly(ownerRepository, ownerId);
40	                if (existing != null) {
41	                    response.send(ownerMapper.toOwnerDto(existing)); // 200; no duplicate created
42	                    return;
43	                }
44	            }
45	        }
46	        proceed.proceed();
47	    }
48	
49	    /** The trimmed {@code Idempotency-Key} value, or {@code null} when absent or blank. */
50	    static String header(ServerHttpConnection connection) {
51	        HttpHeader header = connection.getRequest().getHeaders().getHeader(HEADER);
52	        if (header == null) {
53	            return null;
54	        }
55	        String value = header.getValue();
56	        return (value == null || value.trim().isEmpty()) ? null : value.trim();
57	    }
58	
59	    private static Owner findQuietly(OwnerRepository ownerRepository, Integer ownerId) {
60	        try {
61	            return ownerRepository.findById(ownerId);
62	        }
63	        catch (DataAccessException ex) {
64	            return null; // recorded owner no longer present; fall through to a fresh create
65	        }
66	    }
67	}
