1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Set;
7	import java.util.regex.Pattern;
8	
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
16	 * firstName, lastName, address, city or telephone. Throwing lists every offending field, so the
17	 * client sees them all at once. The address is normalized (trim/collapse whitespace, upper-case, and
18	 * expand ST/RD/AVE) and written back, and is treated as absent when blank after normalization. It
19	 * also normalizes the telephone into E.164 form (keeping a leading
20	 * '+' and country code when present, otherwise assuming '+61' and dropping a single leading '0'),
21	 * rejecting with 400 when it cannot form a valid E.164 number; the normalized value is
22	 * written back onto the body. When an optional {@code email} is present it must be a syntactically
23	 * valid address (else 400); it is lower-cased and written back. A supplied {@code registrationDate}
24	 * later than the server's current date is rejected with 400 (an absent date is accepted and defaults
25	 * to today when the owner is built). On success it publishes the body for {@link BuildOwner} to map.
26	 */
27	public class ValidateOwnerFields {
28	
29	    /** Syntactic email check: a non-empty local part, an {@code @}, then a dotted domain. */
30	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
31	
32	    /** Disposable email domains that are rejected with 400. */
33	    private static final Set<String> DISPOSABLE_DOMAINS =
34	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
35	
36	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
37	            throws OwnerFieldsInvalidException {
38	        List<String> errors = new ArrayList<>();
39	        checkPresent("firstName", request.getFirstName(), errors);
40	        checkPresent("lastName", request.getLastName(), errors);
41	        // The address may be supplied in structured form (a non-blank addressLine1 plus an optional
42	        // addressLine2) or as the flat 'address' input (kept for backward compatibility). Normalize
43	        // whichever fields are supplied (trim/collapse whitespace, upper-case, expand ST/RD/AVE) and
44	        // treat a value that is blank after normalization as absent. The owner is valid when it
45	        // supplies an address in EITHER form.
46	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
47	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
48	        String flatAddress = AddressNormalizer.normalize(request.getAddress());
49	        boolean hasStructured = !line1.isEmpty();
50	        boolean hasFlat = !flatAddress.isEmpty();
51	        if (!hasStructured && !hasFlat) {
52	            errors.add("address");
53	        }
54	        checkPresent("city", request.getCity(), errors);
55	        checkPresent("telephone", request.getTelephone(), errors);
56	        // A supplied registrationDate may not be in the future: reject a date later than the
57	        // server's current date. Absent is accepted (it defaults to today when the owner is built).
58	        LocalDate registrationDate = request.getRegistrationDate();
59	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
60	            errors.add("registrationDate");
61	        }
62	        if (!errors.isEmpty()) {
63	            throw new OwnerFieldsInvalidException(errors);
64	        }
65	        // Store and return the normalized address; later steps read it back via @Val. Prefer the
66	        // structured fields when present: the composed 'address' is the normalized addressLine1, with
67	        // a single space and the normalized addressLine2 appended when addressLine2 is present.
68	        // Otherwise fall back to the normalized flat address.
69	        if (hasStructured) {
70	            request.setAddressLine1(line1);
71	            request.setAddressLine2(line2.isEmpty() ? null : line2);
72	            request.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
73	        }
74	        else {
75	            request.setAddressLine1(null);
76	            request.setAddressLine2(null);
77	            request.setAddress(flatAddress);
78	        }
79	        String telephone = E164Telephone.normalize(request.getTelephone());
80	        if (telephone == null) {
81	            throw new OwnerFieldsInvalidException(List.of("telephone"));
82	        }
83	        request.setTelephone(telephone);
84	        String email = request.getEmail();
85	        if (email != null && !email.trim().isEmpty()) {
86	            email = email.trim();
87	            if (!EMAIL.matcher(email).matches()) {
88	                throw new OwnerFieldsInvalidException(List.of("email"));
89	            }
90	            email = email.toLowerCase();
91	            // Reject disposable-domain addresses (the domain part after the final '@').
92	            String domain = email.substring(email.lastIndexOf('@') + 1);
93	            if (DISPOSABLE_DOMAINS.contains(domain)) {
94	                throw new OwnerFieldsInvalidException(List.of("email"));
95	            }
96	            request.setEmail(email);
97	        }
98	        validated.set(request);
99	    }
100	
101	    private static void checkPresent(String field, String value, List<String> errors) {
102	        if (value == null || value.trim().isEmpty()) {
103	            errors.add(field);
104	        }
105	    }
106	}
