1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Map;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.mapper.OwnerMapper;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
11	
12	/**
13	 * Validates an optional {@code postcode} WHEN PRESENT, then leaves the (already published) body
14	 * untouched. When absent the owner is accepted unchanged, so the request contract stays
15	 * backward-compatible. When present the postcode must be exactly 4 digits and — when the owner's
16	 * city maps to a known region via {@link OwnerMapper#CITY_REGION} (Sydney-&gt;NSW, Melbourne-&gt;VIC,
17	 * Brisbane-&gt;QLD) — must fall within that region's fixed inclusive range (NSW 2000-2099,
18	 * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. A
19	 * malformed or out-of-range postcode is rejected with 400.
20	 */
21	public class ValidatePostcode {
22	
23	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
24	
25	    /** Region -> inclusive 4-digit postcode range {low, high}. */
26	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
27	        "NSW", new int[] {2000, 2099},
28	        "VIC", new int[] {3000, 3099},
29	        "QLD", new int[] {4000, 4099});
30	
31	    public void service(@Val OwnerFieldsDto request) throws OwnerFieldsInvalidException {
32	        String postcode = request.getPostcode();
33	        if (postcode == null || postcode.isBlank()) {
34	            return; // optional when absent
35	        }
36	        postcode = postcode.trim();
37	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
38	            throw new OwnerFieldsInvalidException(List.of("postcode"));
39	        }
40	        String region = OwnerMapper.CITY_REGION.get(request.getCity());
41	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
42	        if (range != null) {
43	            int value = Integer.parseInt(postcode);
44	            if (value < range[0] || value > range[1]) {
45	                throw new OwnerFieldsInvalidException(List.of("postcode"));
46	            }
47	        }
48	    }
49	}
