1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.OwnerCityCapacityConflictException;
7	
8	/**
9	 * Runs before {@link BuildOwner}: rejects the request with 409 when the owner's city already
10	 * contains 50 or more owners (the per-city capacity). The city is compared case-insensitively,
11	 * matching how the customer code's per-city sequence is derived.
12	 */
13	public class CheckOwnerCityCapacity {
14	
15	    private static final long CITY_CAPACITY = 50;
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws OwnerCityCapacityConflictException {
19	        String city = request.getCity();
20	        long inCity = ownerRepository.findAll().stream()
21	                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
22	                .count();
23	        if (inCity >= CITY_CAPACITY) {
24	            throw new OwnerCityCapacityConflictException(
25	                    "The city " + city + " has reached its capacity of " + CITY_CAPACITY + " owners");
26	        }
27	    }
28	}
