1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.OwnerDailyCreateLimitException;
7	
8	/**
9	 * Runs before {@link BuildOwner}: rejects the request with 429 when 100 or more owners have
10	 * already been created today (by registrationDate) — the per-day create limit. Owners' effective
11	 * registrationDate is rolled forward off weekends to the next business day, so this counts against
12	 * the adjusted business day the new owner would be registered on.
13	 */
14	public class CheckOwnerDailyCreateLimit {
15	
16	    private static final long DAILY_LIMIT = 100;
17	
18	    public void service(OwnerRepository ownerRepository) throws OwnerDailyCreateLimitException {
19	        LocalDate businessDay = BusinessDays.rollForward(LocalDate.now());
20	        long createdToday = ownerRepository.findAll().stream()
21	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
22	                .count();
23	        if (createdToday >= DAILY_LIMIT) {
24	            throw new OwnerDailyCreateLimitException(
25	                    "The daily limit of " + DAILY_LIMIT + " owner registrations has been reached");
26	        }
27	    }
28	}
