1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns every owner a deterministic {@code householdId}: the first 12 hex characters of
12	 * {@code SHA-256('V2' + '|' + normalizedLastName + '|' + postcode)}, the version-2 derivation that
13	 * mixes in the fixed {@code 'V2'} tag. The identifier is a pure function of the
14	 * household's last name and postcode, so two owners with the same last name at the same postcode
15	 * share it automatically — no back-fill and no dependence on {@code sharesHousehold} or the order
16	 * owners were created.
17	 *
18	 * <p>The shared householdId is what every household rule keys off: it forms part of each owner's
19	 * {@link OwnerIdentityKey identityKey}, it is the key the household-duplicate check
20	 * ({@link CheckHouseholdUnique}) matches on, and it is the key the household-size input to the
21	 * membership level ({@link AssignHouseholdMemberCount}) groups by. {@code sharesHousehold} no longer
22	 * creates the link; it only bypasses the duplicate block for a declared household member.
23	 */
24	public class AssignHouseholdId {
25	
26	    public void service(@Val Owner owner) {
27	        owner.setHouseholdId(deriveHouseholdId(normalize(owner.getLastName()), postcode(owner)));
28	    }
29	
30	    /**
31	     * The first 12 hex characters of {@code SHA-256('V2' + '|' + normalizedLastName + '|' + postcode)}
32	     * — a stable identifier shared by every owner with the same last name and postcode. The fixed
33	     * {@link OwnerRegion#VERSION_TAG 'V2'} version tag is mixed into the hashed input so every v2
34	     * householdId differs from the v1 value for the same household.
35	     */
36	    private static String deriveHouseholdId(String lastName, String postcode) {
37	        try {
38	            byte[] digest = MessageDigest.getInstance("SHA-256")
39	                    .digest((OwnerRegion.VERSION_TAG + "|" + lastName + "|" + postcode)
40	                            .getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(12);
42	            for (int i = 0; i < 6; i++) {
43	                sb.append(String.format("%02x", digest[i]));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException e) {
48	            throw new IllegalStateException(e);
49	        }
50	    }
51	
52	    /** The postcode as supplied, trimmed; an absent postcode contributes the empty string. */
53	    private static String postcode(Owner owner) {
54	        String postcode = owner.getPostcode();
55	        return postcode == null ? "" : postcode.trim();
56	    }
57	
58	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
59	    private static String normalize(String value) {
60	        if (value == null) {
61	            return "";
62	        }
63	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
64	    }
65	}
