1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdMemberCount}: the number of owners in this owner's household
9	 * (all owners sharing the same computed {@code householdId}) once this create completes, including
10	 * the new owner itself. Runs after {@link AssignHouseholdId} has assigned the deterministic
11	 * {@code householdId}, but before the new owner is saved, so the existing members are counted from
12	 * the repository and the not-yet-persisted new owner is added in as one.
13	 *
14	 * <p>Because the householdId is keyed on (lastName, postcode), the members counted here are exactly
15	 * the owners sharing this owner's last name and postcode.
16	 */
17	public class AssignHouseholdMemberCount {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        int count = 1; // the new owner, not yet saved
22	        if (householdId != null) {
23	            for (Owner existing : ownerRepository.findAll()) {
24	                if (householdId.equals(existing.getHouseholdId())) {
25	                    count++;
26	                }
27	            }
28	        }
29	        owner.setHouseholdMemberCount(count);
30	    }
31	}
