1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share this owner's
9	 * {@code firstName} and {@code lastName}, compared case-insensitively. Runs before the new owner is
10	 * saved, so the count reflects only the owners that existed before this create.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = normalize(owner.getFirstName());
16	        String lastName = normalize(owner.getLastName());
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (firstName.equals(normalize(existing.getFirstName()))
20	                    && lastName.equals(normalize(existing.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    /** Lower-case and trim so namesakes are matched case-insensitively. */
28	    private static String normalize(String value) {
29	        return value == null ? "" : value.trim().toLowerCase();
30	    }
31	}
