1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDate;
7	import java.time.Month;
8	import java.util.HashSet;
9	import java.util.Set;
10	
11	import net.officefloor.plugin.variable.Val;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where REGION is
17	 * the version-2 region code that appears inside the identifiers — the plain region derived from the
18	 * owner's postcode with the fixed {@code 'V2'} tag mixed in (see {@link OwnerRegion#identityRegion},
19	 * e.g. {@code NSWV2}), so the memberId changes and can never equal a v1 one. The user-facing
20	 * {@code locality} keeps the plain region. FY is the 2-digit fiscal year of the owner's registrationDate (the same YY
21	 * as the {@code fiscalYear} field), HASH8 is the first 8 upper-case hex characters of SHA-256 over
22	 * the owner's normalized (E.164) telephone concatenated with the last name, and CHK is a single Luhn
23	 * check digit computed over the digits of {@code <REGION><FY><HASH8>}.
24	 *
25	 * <p>The identity is therefore a stable function of who the owner is, not of how many owners already
26	 * exist — the old per-city sequence number is gone. This unifies what used to be the separate
27	 * {@code customerCode}, {@code membershipNumber} and {@code checkDigit}.
28	 *
29	 * <p>Should the computed memberId collide with an existing owner's {@code memberId}, it is
30	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
31	 * unique, so distinct owners always end up with distinct member ids.
32	 */
33	public class AssignMemberId {
34	
35	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
36	        String region = OwnerRegion.identityRegion(owner);
37	        String fy = fiscalYear2(owner.getRegistrationDate());
38	        String hash8 = hash8(normalizedTelephone(owner.getTelephone()) + owner.getLastName());
39	        String body = region + fy + hash8;
40	        String base = body + luhn(body);
41	        owner.setMemberId(deduplicate(base, existingMemberIds(ownerRepository)));
42	    }
43	
44	    /** The {@code memberId}s already assigned to other owners in the data store. */
45	    private static Set<String> existingMemberIds(OwnerRepository ownerRepository) {
46	        Set<String> ids = new HashSet<>();
47	        for (Owner existing : ownerRepository.findAll()) {
48	            String id = existing.getMemberId();
49	            if (id != null) {
50	                ids.add(id);
51	            }
52	        }
53	        return ids;
54	    }
55	
56	    /**
57	     * Returns {@code base} if it is not already taken; otherwise appends {@code -<n>} with the
58	     * smallest {@code n} of 2 or more that makes it unique.
59	     */
60	    private static String deduplicate(String base, Set<String> taken) {
61	        if (!taken.contains(base)) {
62	            return base;
63	        }
64	        for (int n = 2; ; n++) {
65	            String candidate = base + "-" + n;
66	            if (!taken.contains(candidate)) {
67	                return candidate;
68	            }
69	        }
70	    }
71	
72	    /**
73	     * The last two digits of the fiscal year (1 July - 30 June, named by the calendar year in which
74	     * it ends) of {@code date}, zero-padded. Falls back to the current date's fiscal year when no
75	     * registration date is present.
76	     */
77	    private static String fiscalYear2(LocalDate date) {
78	        LocalDate d = date != null ? date : LocalDate.now();
79	        int fy = d.getMonthValue() >= Month.JULY.getValue() ? d.getYear() + 1 : d.getYear();
80	        return String.format("%02d", Math.floorMod(fy, 100));
81	    }
82	
83	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
84	    private static int luhn(String s) {
85	        int sum = 0;
86	        boolean dbl = true;
87	        for (int i = s.length() - 1; i >= 0; i--) {
88	            char c = s.charAt(i);
89	            if (c < '0' || c > '9') {
90	                continue;
91	            }
92	            int d = c - '0';
93	            if (dbl) {
94	                d *= 2;
95	                if (d > 9) {
96	                    d -= 9;
97	                }
98	            }
99	            sum += d;
100	            dbl = !dbl;
101	        }
102	        return (10 - (sum % 10)) % 10;
103	    }
104	
105	    /**
106	     * The owner's telephone normalized to E.164 (the same way {@link OwnerIdentityKey} does),
107	     * falling back to the trimmed raw value when it cannot form a valid E.164 number. On the create
108	     * path the telephone was already normalized upstream, so this is idempotent.
109	     */
110	    private static String normalizedTelephone(String raw) {
111	        if (raw == null) {
112	            return "";
113	        }
114	        String normalized = E164Telephone.normalize(raw);
115	        return normalized != null ? normalized : raw.trim();
116	    }
117	
118	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
119	    private static String hash8(String s) {
120	        try {
121	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
122	            StringBuilder sb = new StringBuilder();
123	            for (byte b : digest) {
124	                sb.append(String.format("%02X", b));
125	                if (sb.length() >= 8) {
126	                    break;
127	                }
128	            }
129	            return sb.substring(0, 8);
130	        }
131	        catch (NoSuchAlgorithmException ex) {
132	            throw new IllegalStateException("SHA-256 not available", ex);
133	        }
134	    }
135	}
