6	
7	/**
8	 * Soft-match detection for {@code POST /api/owners}: an owner that is <em>not</em> a hard
9	 * ({@link OwnerIdentityKey identityKey}) duplicate but nonetheless matches an existing owner's
10	 * {@code soundex(lastName)} and {@code postcode} is still created, and flagged. Sets
11	 * {@code possibleDuplicate} to {@code true} and {@code possibleDuplicateOf} to the matching owner's
12	 * id when such a match exists; otherwise {@code possibleDuplicate} is {@code false} and
13	 * {@code possibleDuplicateOf} is left absent.
14	 *
15	 * <p>Because the identityKey now folds in the telephone, two owners with the same last name and
16	 * postcode but different telephones have different keys — they are no longer a hard duplicate but a
17	 * soft match, caught here. The match is therefore keyed on the same {@link OwnerIdentityKey#soundex
18	 * Soundex} of the last name that the identityKey uses, plus an exact postcode, and only fires when
19	 * the two owners' whole identityKeys actually differ (an equal key would already have been rejected
20	 * with 409 upstream).
21	 *
22	 * <p>Runs after {@link CheckOwnerIdentityUnique} (so a hard duplicate has already been rejected with
23	 * 409 and never reaches here) and before {@link SaveOwner} (so the not-yet-saved owner is not
24	 * compared against itself). When more than one existing owner matches, the earliest (lowest id) is
25	 * reported, for a deterministic result.
26	 */
27	public class AssignPossibleDuplicate {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String postcode = owner.getPostcode();
31	        Integer matchId = null;
32	        if (owner.getLastName() != null && postcode != null && !postcode.isBlank()) {
33	            String soundex = OwnerIdentityKey.soundex(owner.getLastName());
34	            String identityKey = OwnerIdentityKey.of(owner);
35	            for (Owner existing : ownerRepository.findAll()) {
36	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
37	                    continue;
38	                }
39	                if (existing.getId() == null) {
40	                    continue;
41	                }
42	                if (!soundex.equals(OwnerIdentityKey.soundex(existing.getLastName()))) {
43	                    continue;
44	                }
45	                if (!postcode.equals(existing.getPostcode())) {
46	                    continue;
47	                }
48	                // Equal identityKeys are a hard duplicate (already a 409), not a soft match.
49	                if (identityKey.equals(OwnerIdentityKey.of(existing))) {
50	                    continue;
51	                }
52	                if (matchId == null || existing.getId() < matchId) {
53	                    matchId = existing.getId();
54	                }
55	            }
56	        }
57	        owner.setPossibleDuplicate(matchId != null);
58	        owner.setPossibleDuplicateOf(matchId);
59	    }
60	}
