3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Emits an audit line on the dedicated {@code AUDIT} logger after a successful create,
15	 * carrying the newly-assigned owner id, its memberId, its registrationDate and its
16	 * numeric membershipLevel. Runs after {@code save}, so the owner's generated id is
17	 * available. The logged level is the household-capped one, so it matches what the response
18	 * and later reads return.
19	 *
20	 * <p>Alongside the human-readable line, emits an immutable structured event on the same
21	 * {@code AUDIT} logger. The event is now schema version 2: a JSON object
22	 * {@code {seq, schemaVersion:2, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} where
23	 * {@code seq} is a monotonically increasing integer across creates. The event carries the
24	 * owner's primary identifier via {@link #primaryIdentifier(Owner)} — the version-2 memberId.
25	 */
26	public class AuditOwnerCreated {
27	
28	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
29	
30	    /** Monotonically increasing sequence across all creates in this instance. */
31	    private static final AtomicLong SEQ = new AtomicLong();
32	
33	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository) {
34	        int membershipLevel = HouseholdLevelCap.cappedMembershipLevel(owner, ownerMapper, ownerRepository);
35	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
36	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
37	
38	        long seq = SEQ.incrementAndGet();
39	        AUDIT.info("{\"seq\":{},\"schemaVersion\":2,\"ownerId\":{},\"memberId\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
40	            seq, owner.getId(), jsonString(primaryIdentifier(owner)), membershipLevel);
41	    }
42	
43	    /** The owner's primary identifier carried by the structured event: the {@code memberId}. */
44	    private static String primaryIdentifier(Owner owner) {
45	        return owner.getMemberId();
46	    }
47	
48	    /** Renders a value as a JSON string literal (quoted, with the minimal escaping), or {@code null}. */
49	    private static String jsonString(String value) {
50	        if (value == null) {
51	            return "null";
52	        }
53	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
54	        for (int i = 0; i < value.length(); i++) {
55	            char c = value.charAt(i);
56	            switch (c) {
57	                case '"' -> sb.append("\\\"");
58	                case '\\' -> sb.append("\\\\");
59	                case '\n' -> sb.append("\\n");
60	                case '\r' -> sb.append("\\r");
61	                case '\t' -> sb.append("\\t");
62	                default -> sb.append(c);
63	            }
64	        }
65	        return sb.append('"').toString();
66	    }
67	}
