2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "initials",
26	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "apiVersion", expression = "java(2)")
29	    @Mapping(target = "identity", expression = "java(identity(owner))")
30	    @Mapping(target = "telephoneDisplay",
31	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.E164Telephone.display(owner.getTelephone()))")
32	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
37	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives the owner's salutation: the {@code title} and {@code lastName} separated by a single
44	     * space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when no title was supplied.
45	     */
46	    default String salutation(Owner owner) {
47	        String title = owner.getTitle();
48	        if (title == null || title.isBlank()) {
49	            return owner.getLastName();
50	        }
51	        return title + " " + owner.getLastName();
52	    }
53	
54	    /**
55	     * Derives the owner's age band from {@code birthDate}, computed against the
56	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18-64,
57	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date was supplied
58	     * (or the registration date is absent, e.g. seed data), so the field is simply absent.
59	     */
60	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        java.time.LocalDate birthDate = owner.getBirthDate();
62	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
63	        if (birthDate == null || registrationDate == null) {
64	            return null;
65	        }
66	        int years = java.time.Period.between(birthDate, registrationDate).getYears();
67	        if (years < 18) {
68	            return OwnerDto.AgeBandEnum.MINOR;
69	        }
70	        if (years < 65) {
71	            return OwnerDto.AgeBandEnum.ADULT;
72	        }
73	        return OwnerDto.AgeBandEnum.SENIOR;
74	    }
75	
76	    /**
77	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
78	     * present, otherwise {@code PHONE}.
79	     */
80	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
81	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
82	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
83	    }
84	
85	    /**
86	     * The second-level labels of the known disposable email domains (the blocklist enforced by
87	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields}:
88	     * {@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). An email whose
89	     * domain carries one of these labels is <em>disposable-adjacent</em>.
90	     */
91	    java.util.Set<String> DISPOSABLE_ADJACENT_LABELS = java.util.Set.of(
92	        "mailinator", "tempmail", "guerrillamail");
93	
94	    /**
95	     * Derives the owner's risk flag: {@code true} when any of these hold, otherwise {@code false}:
96	     * the owner is a possible duplicate ({@code possibleDuplicate}), its email domain is
97	     * {@link #disposableAdjacentEmail(Owner) disposable-adjacent}, or its city is over its soft
98	     * capacity (the approaching-capacity {@code capacityWarning}).
99	     */
100	    default boolean riskFlag(Owner owner) {
101	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
102	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
103	        return possibleDuplicate || overSoftCapacity || disposableAdjacentEmail(owner);
104	    }
105	
106	    /**
107	     * Whether the owner's email domain is disposable-adjacent: it carries one of the
108	     * {@link #DISPOSABLE_ADJACENT_LABELS known disposable labels} as one of its dot-separated
109	     * labels (e.g. {@code mailinator.net} or {@code sub.tempmail.co}). The exact blocklisted
110	     * domains never reach here (they are rejected with 400 at validation), so this catches the
111	     * look-alikes around them. Returns {@code false} when no email is present.
112	     */
113	    default boolean disposableAdjacentEmail(Owner owner) {
114	        String email = owner.getEmail();
115	        if (email == null || email.isBlank()) {
116	            return false;
117	        }
118	        int at = email.lastIndexOf('@');
119	        if (at < 0) {
120	            return false;
121	        }
122	        String domain = email.substring(at + 1).toLowerCase();
123	        for (String label : domain.split("\\.")) {
124	            if (DISPOSABLE_ADJACENT_LABELS.contains(label)) {
125	                return true;
126	            }
127	        }
128	        return false;
129	    }
130	
131	    /**
132	     * The fixed city-to-region table: any city not listed derives locality {@code UNKNOWN}.
133	     */
134	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
135	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
136	
137	    /**
138	     * The fixed region-to-timezone table: maps a region code to its IANA timezone name. Any region
139	     * not listed (e.g. {@code UNKNOWN}) has no timezone.
140	     */
141	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
142	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
143	
144	    /**
145	     * Derives the owner's IANA timezone from the {@link #locality(Owner) locality/region} via the
146	     * fixed {@link #REGION_TIMEZONE} table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
147	     * QLD-&gt;Australia/Brisbane). Returns {@code null} when the region is not one of these, so the
148	     * field is simply absent.
149	     */
150	    default String timezone(Owner owner) {
151	        return REGION_TIMEZONE.get(locality(owner));
152	    }
153	
154	    /**
155	     * Derives the owner's user-facing locality: the plain region code
156	     * ({@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion}, postcode range
157	     * first — NSW 2000-2099, VIC 3000-3099, QLD 4000-4099 — then the city table, then {@code UNKNOWN}).
158	     * This is the same base region the identity is built from, but WITHOUT the identifiers' {@code 'V2'}
159	     * tag, so a Sydney owner reads back locality {@code "NSW"} even though the memberId's internal
160	     * region is {@code "NSWV2"}. Deriving it directly (rather than from the memberId prefix) keeps the
161	     * locality free of the identifier tag.
162	     */
163	    default String locality(Owner owner) {
164	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.of(owner);
165	    }
166	
167	    /**
168	     * Groups the owner's version-2 identifiers under the response's nested {@code identity} object:
169	     * the {@code memberId} and {@code householdId} assigned during create and the {@code identityKey}
170	     * derived on read ({@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey}).
171	     */
172	    default org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto identity(Owner owner) {
173	        org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto identity =
174	            new org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto();
175	        identity.setMemberId(owner.getMemberId());
176	        identity.setHouseholdId(owner.getHouseholdId());
177	        identity.setIdentityKey(
