83	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
84	    private static int luhn(String s) {
85	        int sum = 0;
86	        boolean dbl = true;
87	        for (int i = s.length() - 1; i >= 0; i--) {
88	            char c = s.charAt(i);
89	            if (c < '0' || c > '9') {
