        long inCity = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        owner.setCapacityWarning(inCity >= WARNING_LOWER && inCity <= WARNING_UPPER);
    }
}

