2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is expressed
12	 * through. It is the SHA-256, rendered as 64 lower-case hex characters, of
13	 * {@code 'V2' + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} — the
14	 * version-2 derivation that mixes in the fixed {@code 'V2'} tag, where the email segment
15	 * is empty when the owner has none. Two owners are the same identity when their whole identityKey is
16	 * equal; because the telephone is part of the key, two people with the same last name (same soundex)
17	 * and postcode but <em>different</em> telephones have different keys and are both allowed — they are
18	 * a soft match, not a hard duplicate.
19	 *
20	 * <p>The telephone is normalized to E.164 (the same way as {@link E164Telephone}) and the email is
21	 * trimmed and lower-cased, so differently-formatted values still produce the same key. The last name
22	 * is reduced to its {@link #soundex(String) Soundex} code, so phonetically-equal surnames share the
23	 * same key segment. The key is computed identically for a not-yet-saved owner (in
24	 * {@link CheckOwnerIdentityUnique}) and for the response, so what a client reads back is exactly what
25	 * collisions are judged on.
26	 */
27	public final class OwnerIdentityKey {
28	
29	    private OwnerIdentityKey() {
30	    }
31	
32	    /**
33	     * The owner's identity key: the 64-hex SHA-256 of
34	     * {@code 'V2'|telephone|email|soundex(lastName)}. The fixed {@link OwnerRegion#VERSION_TAG 'V2'}
35	     * version tag is mixed into the hashed input, so every v2 identityKey differs from the v1 value
36	     * for the same owner while equality (what duplicate detection keys off) is preserved.
37	     */
38	    public static String of(Owner owner) {
39	        String raw = OwnerRegion.VERSION_TAG + "|" + normalizeTelephone(owner.getTelephone()) + "|"
40	                + normalizeEmail(owner.getEmail()) + "|" + soundex(owner.getLastName());
41	        return sha256Hex(raw);
42	    }
43	
44	    private static String normalizeTelephone(String raw) {
45	        if (raw == null) {
46	            return "";
47	        }
48	        String normalized = E164Telephone.normalize(raw);
49	        return normalized != null ? normalized : raw.trim();
50	    }
51	
52	    private static String normalizeEmail(String email) {
53	        if (email == null) {
54	            return "";
55	        }
56	        String trimmed = email.trim();
57	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
58	    }
59	
60	    /** Lower-case hex SHA-256 digest of the given value. */
61	    private static String sha256Hex(String value) {
62	        try {
63	            byte[] digest = MessageDigest.getInstance("SHA-256")
64	                    .digest(value.getBytes(StandardCharsets.UTF_8));
65	            StringBuilder sb = new StringBuilder(digest.length * 2);
66	            for (byte b : digest) {
67	                sb.append(String.format("%02x", b));
68	            }
69	            return sb.toString();
70	        }
71	        catch (NoSuchAlgorithmException e) {
72	            throw new IllegalStateException(e);
73	        }
74	    }
75	
76	    /**
77	     * The American Soundex code of a name: the first letter followed by three digits, so that
78	     * phonetically-similar surnames share a code. A {@code null}, empty, or letter-free value yields
79	     * the empty string.
80	     */
81	    public static String soundex(String value) {
82	        if (value == null) {
83	            return "";
84	        }
85	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
86	        if (letters.isEmpty()) {
87	            return "";
88	        }
89	        StringBuilder code = new StringBuilder();
90	        char first = letters.charAt(0);
91	        code.append(first);
92	        char previous = digit(first);
93	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
94	            char c = letters.charAt(i);
95	            char d = digit(c);
96	            if (d != '0' && d != previous) {
97	                code.append(d);
98	            }
99	            // 'H' and 'W' do not reset the running code (so consonants they separate still merge);
100	            // every other letter, vowels included, does.
101	            if (c != 'H' && c != 'W') {
102	                previous = d;
103	            }
104	        }
105	        while (code.length() < 4) {
106	            code.append('0');
107	        }
108	        return code.toString();
109	    }
110	
111	    /** Soundex digit for a letter; {@code '0'} for vowels and the ignored letters (H, W, Y). */
112	    private static char digit(char c) {
113	        switch (c) {
114	            case 'B': case 'F': case 'P': case 'V':
115	                return '1';
116	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
117	                return '2';
118	            case 'D': case 'T':
119	                return '3';
120	            case 'L':
121	                return '4';
122	            case 'M': case 'N':
123	                return '5';
124	            case 'R':
125	                return '6';
126	            default:
127	                return '0';
128	        }
129	    }
130	}
