1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Derives an owner's REGION code — the single source of truth now shared by both the region prefix
10	 * of the {@code memberId} and the owner's locality. The postcode decides first (NSW 2000-2099,
11	 * VIC 3000-3099, QLD 4000-4099); when the postcode is absent or in no known range, the fixed
12	 * city-to-region table ({@link OwnerMapper#CITY_REGION}: Sydney-&gt;NSW, Melbourne-&gt;VIC,
13	 * Brisbane-&gt;QLD) is consulted, falling back to {@code UNKNOWN} for an unlisted city.
14	 */
15	public final class OwnerRegion {
16	
17	    /**
18	     * The fixed version-2 tag mixed into the region code as it appears INSIDE the identifiers. It is
19	     * intentionally NOT a plain letters-only region, so a v2 identifier's region can never coincide
20	     * with a v1 (plain-region) one.
21	     */
22	    public static final String VERSION_TAG = "V2";
23	
24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
26	        "NSW", new int[] {2000, 2099},
27	        "VIC", new int[] {3000, 3099},
28	        "QLD", new int[] {4000, 4099});
29	
30	    private OwnerRegion() {
31	    }
32	
33	    /** The owner's region code: postcode range first, then the city table, then {@code UNKNOWN}. */
34	    public static String of(Owner owner) {
35	        String byPostcode = fromPostcode(owner.getPostcode());
36	        if (byPostcode != null) {
37	            return byPostcode;
38	        }
39	        return OwnerMapper.CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
40	    }
41	
42	    /**
43	     * The region code as it appears INSIDE the version-2 identifiers: the plain {@link #of(Owner)
44	     * region} with the fixed {@link #VERSION_TAG 'V2'} tag mixed in (e.g. {@code "NSWV2"}). This is
45	     * used only to build identifiers (the {@code memberId} region prefix); the user-facing
46	     * {@code locality}, {@code timezone} and owner-segment region keep the plain region, never this.
47	     */
48	    public static String identityRegion(Owner owner) {
49	        return of(owner) + VERSION_TAG;
50	    }
51	
52	    /**
53	     * Maps a postcode to its region by range, or {@code null} when the postcode is absent,
54	     * non-numeric or in no known range.
55	     */
56	    private static String fromPostcode(String postcode) {
57	        if (postcode == null || postcode.isBlank()) {
58	            return null;
59	        }
60	        int code;
61	        try {
62	            code = Integer.parseInt(postcode.trim());
63	        }
64	        catch (NumberFormatException ex) {
65	            return null;
66	        }
67	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
68	            int[] range = entry.getValue();
69	            if (code >= range[0] && code <= range[1]) {
70	                return entry.getKey();
71	            }
72	        }
73	        return null;
74	    }
75	}
