3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day helper for owner registration. The effective registration date must fall on a
9	 * business day: a Saturday, Sunday or listed public holiday rolls forward to the next
10	 * non-holiday weekday.
11	 */
12	public final class BusinessDays {
13	
14	    /** Fixed public holidays the business-day roll skips. */
15	    private static final Set<LocalDate> HOLIDAYS = Set.of(
16	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
17	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
18	            LocalDate.parse("2026-12-28"));
19	
20	    private BusinessDays() {
21	    }
22	
23	    /**
24	     * Rolls {@code date} forward to the next business day when it falls on a weekend or a listed
25	     * public holiday, leaving an ordinary weekday unchanged. A Saturday rolls to the following
26	     * Monday, a Sunday to the next day, and a holiday to the next non-holiday business day.
27	     */
28	    public static LocalDate rollForward(LocalDate date) {
29	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
30	                || HOLIDAYS.contains(date)) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	}
