10	/**
11	 * Applies the household ceiling to an owner's membership level: a new owner's
12	 * {@code membershipLevel} cannot exceed one above the current maximum membership level among the
13	 * other members of their household (all owners sharing the same {@code householdId}). With no other
14	 * household member, no cap applies and the owner's own level is returned unchanged.
15	 *
16	 * <p>Each existing member's level is evaluated at the household's <em>current</em> size (the number
17	 * of members sharing the household now, including this owner), not the size stored on that member
18	 * when it was created — so a household that has since grown to three or more lifts every member's
19	 * household-size bonus, and with it the ceiling.
20	 */
21	public final class HouseholdLevelCap {
22	
23	    private HouseholdLevelCap() {
24	    }
25	
26	    /**
27	     * The owner's membership level capped at one above the maximum level among their other household
28	     * members, or their own level when the household has no other member.
29	     */
30	    public static int cappedMembershipLevel(Owner owner, OwnerMapper ownerMapper,
31	            OwnerRepository ownerRepository) {
32	        int ownLevel = ownerMapper.membershipLevel(owner);
33	        String householdId = owner.getHouseholdId();
34	        if (householdId == null) {
35	            return ownLevel;
36	        }
37	        List<Owner> members = new ArrayList<>();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (householdId.equals(existing.getHouseholdId())
40	                    && (owner.getId() == null || !owner.getId().equals(existing.getId()))) {
41	                members.add(existing);
42	            }
43	        }
44	        if (members.isEmpty()) {
45	            return ownLevel;
46	        }
47	        int currentHouseholdSize = members.size() + 1; // the other members plus this owner
48	        int maxMemberLevel = 0;
49	        for (Owner member : members) {
50	            maxMemberLevel = Math.max(maxMemberLevel,
51	                    ownerMapper.membershipLevelForHousehold(member, currentHouseholdSize));
52	        }
53	        return Math.min(ownLevel, maxMemberLevel + 1);
54	    }
55	}
