8	/**
9	 * Process-wide registry mapping a {@code POST /api/owners} request's {@code Idempotency-Key} to the
10	 * id of the owner that request created. A later create repeating an already-recorded key is answered
11	 * with the originally created owner instead of creating a duplicate.
12	 */
13	@Component
14	public class IdempotencyStore {
15	
16	    private final Map<String, Integer> keyToOwnerId = new ConcurrentHashMap<>();
17	
18	    /** The owner id recorded for {@code key}, or {@code null} when the key is unknown or {@code null}. */
19	    public Integer find(String key) {
20	        return key == null ? null : keyToOwnerId.get(key);
21	    }
22	
23	    /** Record {@code ownerId} against {@code key}; a no-op when either is {@code null}. */
24	    public void record(String key, Integer ownerId) {
25	        if (key != null && ownerId != null) {
26	            keyToOwnerId.put(key, ownerId);
27	        }
28	    }
29	}
